#include <cstdio>
#include <algorithm>
#include <iostream>
#include <cstdlib>

using namespace std;

using LL = long long;

const LL INF = 1000000009LL;

LL findB(LL x, LL y, LL a) {
    LL low = -INF;
    LL high = INF;

    while (low < high) {
        LL mid = low + (high - low) / 2;
        LL val = x - y - 2LL * a * mid;

        if (val < 0)
            high = mid;
        else
            low = mid + 1;
    }

    return low;
}

LL findA(LL x, LL y, LL a) {
    LL low = -INF;
    LL high = INF;

    while (low < high) {
        LL mid = low + (high - low) / 2;
        LL val = x + y - 2LL * a * mid;

        if (val < 0)
            high = mid;
        else
            low = mid + 1;
    }

    return low;
}

int main() {
    LL a, b, x1, y1, x2, y2;
    cin >> a >> b >> x1 >> y1 >> x2 >> y2;

    LL a1 = findA(x1, y1, a);
    LL a2 = findA(x2, y2, a);
    LL b1 = findB(x1, y1, b);
    LL b2 = findB(x2, y2, b);

